_normalize_source = '"""Step 2 — universal normalisation (master plan SS8 / architecture.md SS4).\n\nApplied identically to every record from every source and country. No\ncountry value, word list per country, or external resource is used: the only\nlists are tiny, language-neutral trigger sets (connectors, landmark\ntriggers, number suffixes) named in the master plan. Everything else is\ndriven by Unicode properties from the stdlib `unicodedata` module.\n\nOutput fields per record (see `normalize_df`):\n- `norm_name`, `norm_addr`: casefolded, accent-stripped, Brahmic scripts\n  romanised, punctuation -> spaces, dotted initials joined, domains reduced\n  to their label, landmark phrase removed from the address.\n- `fold_name`, `fold_addr`: phonetic/transliteration fold of the norm text\n  (vowel-run reduction, digraphs, doubled consonants). Used *alongside*\n  norm features, never instead of them.\n- `name_numbers`, `addr_numbers`: space-joined digit-bearing tokens.\n- `house_number`: first digit-bearing token of the address.\n- `postcodes`: shape-based postcode candidates (4-6 digit runs, or mixed\n  letter/digit tokens, in the last two comma segments, never the house\n  number). EDA E11 showed a naive "last digit run" mostly finds house\n  numbers, hence the position rule.\n- `landmark`: trigger + up to 4 tokens of a landmark phrase ("near X").\n- `name_romanized`: True if the name contained a Brahmic script that was\n  romanised (a later feature, and a bug-detection aid).\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport re\nimport time\nimport unicodedata\nfrom functools import lru_cache\nfrom multiprocessing import Pool\n\nimport pandas as pd\n\nlog = logging.getLogger(__name__)\n\n# ---------------------------------------------------------------------------\n# Small language-neutral trigger sets (master plan SS8.1). Not country lists.\n# ---------------------------------------------------------------------------\n_CONNECTORS = {"and", "et", "und", "&"}\n# Multi-word triggers are matched as token tuples, longest first.\n_LANDMARK_TRIGGERS = sorted(\n    [\n        ("near",), ("nr",), ("opp",), ("opposite",), ("behind",), ("beside",), ("besides",),\n        ("adjacent",), ("next", "to"), ("in", "front", "of"), ("pres", "de"), ("en", "face", "de"),\n        ("derriere",), ("a", "cote", "de"),\n    ],\n    key=len,\n    reverse=True,\n)\n_LANDMARK_MAX_TOKENS = 4\n_NULL_TOKENS = {"null", "nan"}  # literal missing-value markers seen inside S2 addresses\n\n_LIGATURES = str.maketrans({"œ": "oe", "æ": "ae", "ß": "ss", "ø": "o", "đ": "d", "ł": "l", "ı": "i"})\n_QUOTES = str.maketrans({"’": "\'", "‘": "\'", "ʼ": "\'", "`": "\'", "´": "\'"})\n\n_COMBINING_LATIN_RE = re.compile(r"[̀-ͯ]+")  # diacritics block (Latin/Greek/Cyrillic only)\n_DOMAIN_RE = re.compile(r"^(?:https?://)?(?:www\\.)?([^\\W_][\\w-]*?)(?:\\.[a-z]{2,6}){1,2}/?$")\n_URL_PREFIX_RE = re.compile(r"(?:https?://)?www\\.")\n_INITIALS_RE = re.compile(r"(?<![^\\W\\d_])((?:[^\\W\\d_]\\.){2,})")\n_NUM_SUFFIX_RE = re.compile(r"(\\d+)\\s*[- ]?\\s*(bis|ter|quater)(?![^\\W\\d_])")\n_NON_WORD_RE = re.compile(r"[^\\w&]|_")\n_WS_RE = re.compile(r"\\s+")\n_DIGIT_RE = re.compile(r"\\d")\n_POSTCODE_DIGITS_RE = re.compile(r"^\\d{4,6}$")\n# Mixed postcodes start with a letter ("sw1a", "h3z"); "3rd"/"12b" are house numbers or ordinals.\n_POSTCODE_MIXED_RE = re.compile(r"^[a-z]{1,2}\\d[a-z0-9]{0,2}$")\n\n# Phonetic fold rules, applied in order (master plan SS8.1 step 8).\n_FOLD_RULES = [\n    (re.compile(r"ph"), "f"),\n    (re.compile(r"sh"), "s"),\n    (re.compile(r"th"), "t"),\n    (re.compile(r"kh"), "k"),\n    (re.compile(r"gh"), "g"),\n    (re.compile(r"ck"), "k"),\n    (re.compile(r"qu"), "k"),\n    (re.compile(r"w"), "v"),\n    (re.compile(r"z"), "s"),\n    (re.compile(r"ee"), "i"),\n    (re.compile(r"oo"), "u"),\n    (re.compile(r"([aiu])\\1+"), r"\\1"),  # aa->a, ii->i, uu->u\n    (re.compile(r"([b-df-hj-np-tv-xz])\\1+"), r"\\1"),  # doubled consonants\n]\n\n# ---------------------------------------------------------------------------\n# Brahmic-script romanisation from Unicode character names (stdlib only).\n# A script counts as Brahmic if it has a "<SCRIPT> SIGN VIRAMA" character, so\n# Devanagari, Kannada, Tamil, Bengali, ... all work without listing them.\n# ---------------------------------------------------------------------------\n_VOWEL_NAMES = {\n    "A", "AA", "I", "II", "U", "UU", "E", "EE", "AI", "O", "OO", "AU",\n    "VOCALIC R", "VOCALIC RR", "VOCALIC L", "VOCALIC LL", "SHORT E", "SHORT O",\n    "CANDRA E", "CANDRA O",\n}\n_NAME_PARTS_RE = re.compile(r"^(.*?) (LETTER|VOWEL SIGN|SIGN|DIGIT) (.+)$")\n\n\n@lru_cache(maxsize=None)\ndef _is_brahmic_script(script: str) -> bool:\n    """True if Unicode defines `<script> SIGN VIRAMA` (the Brahmic-family marker).\n\n    Inputs: script - script prefix of a character name, e.g. "DEVANAGARI".\n    Outputs: bool.\n    """\n    try:\n        unicodedata.lookup(f"{script} SIGN VIRAMA")\n        return True\n    except KeyError:\n        return False\n\n\ndef _vowel_latin(vname: str) -> str:\n    """Map a vowel name ("AA", "VOCALIC R", "CANDRA E") to a Latin string."""\n    parts = vname.split()\n    if parts[0] == "VOCALIC":\n        return "ri" if parts[-1].startswith("R") else "li"\n    v = parts[-1].lower()\n    # Long vowels map to one letter: Latin spellings rarely double them.\n    return v[0] if len(v) == 2 and v[0] == v[1] else v\n\n\n@lru_cache(maxsize=None)\ndef _char_role(ch: str) -> tuple[str, str]:\n    """Classify one character for romanisation.\n\n    Inputs: ch - a single character.\n    Outputs: (role, latin) where role is one of "cons" (consonant with an\n    inherent vowel), "vowel" (independent vowel), "sign" (dependent vowel\n    sign), "virama", "nasal", "visarga", "digit", "skip" (nukta etc.), or\n    "other" (not a Brahmic character; kept unchanged).\n    """\n    if ch.isascii():\n        return ("other", ch)\n    name = unicodedata.name(ch, "")\n    m = _NAME_PARTS_RE.match(name)\n    if not m or not _is_brahmic_script(m.group(1)):\n        return ("other", ch)\n    kind, rest = m.group(2), m.group(3)\n    if kind == "DIGIT":\n        return ("digit", str(unicodedata.digit(ch, 0)))\n    if kind == "VOWEL SIGN":\n        return ("sign", _vowel_latin(rest))\n    if kind == "SIGN":\n        if rest == "VIRAMA":\n            return ("virama", "")\n        if rest in ("ANUSVARA", "CANDRABINDU"):\n            return ("nasal", "n")\n        if rest == "VISARGA":\n            return ("visarga", "h")\n        return ("skip", "")\n    # LETTER\n    if rest in _VOWEL_NAMES:\n        return ("vowel", _vowel_latin(rest))\n    last = rest.split()[-1].lower()\n    if last.endswith("a"):\n        base = last[:-1] or last\n        # Retroflex consonants are named with a doubled letter (TTA, DDA,\n        # NNA); Latin spellings use a single one.\n        if len(base) == 2 and base[0] == base[1]:\n            base = base[0]\n        return ("cons", base)\n    return ("other", ch)\n\n\n@lru_cache(maxsize=200_000)\ndef romanize_word(word: str) -> str:\n    """Romanise one word written in a Brahmic script; other characters pass through.\n\n    Consonants carry an inherent "a" that a vowel sign replaces and a virama\n    removes; a word-final inherent "a" is dropped (schwa deletion), which\n    matches common Latin spellings ("राम" -> "ram"). The final "a" is kept\n    after a conjunct cluster ("राष्ट्र" -> "rashtra"), again as in common\n    spellings.\n\n    Inputs: word - one whitespace-free token.\n    Outputs: Latin approximation (lowercase), or the word unchanged if it has\n    no Brahmic characters.\n    """\n    out: list[str] = []\n    pending_a = False  # a consonant was just emitted and still owns its inherent \'a\'\n    prev_virama = False  # the previous character was a virama\n    in_conjunct = False  # the pending consonant closes a conjunct cluster\n    for ch in word:\n        role, lat = _char_role(ch)\n        if role == "cons":\n            if pending_a:\n                out.append("a")\n            out.append(lat)\n            in_conjunct = prev_virama\n            pending_a = True\n        elif role == "sign":\n            out.append(lat)\n            pending_a = False\n        elif role in ("vowel", "digit", "other", "nasal", "visarga"):\n            if pending_a:\n                out.append("a")\n            out.append(lat)\n            pending_a = False\n        # "skip": nukta and similar marks change nothing\n        prev_virama = role == "virama"\n        if prev_virama:\n            pending_a = False\n    if pending_a and in_conjunct:\n        out.append("a")\n    return "".join(out)\n\n\ndef _romanize_text(text: str) -> tuple[str, bool]:\n    """Romanise every Brahmic-script word in a string.\n\n    Inputs: text - casefolded text.\n    Outputs: (romanised text, True if anything was romanised).\n    """\n    words = text.split()\n    changed = False\n    for i, w in enumerate(words):\n        if not w.isascii():\n            r = romanize_word(w)\n            if r != w:\n                words[i] = r\n                changed = True\n    return " ".join(words), changed\n\n\n# ---------------------------------------------------------------------------\n# Core text normalisation\n# ---------------------------------------------------------------------------\ndef _unicode_clean(text: str) -> str:\n    """NFKC + casefold + ligatures + accent stripping (Latin diacritics only).\n\n    Combining marks in the U+0300-U+036F block are removed after NFKD; marks\n    of other scripts (e.g. Devanagari vowel signs) are kept, because deleting\n    them would destroy the word (master plan SS8.3: never delete what we\n    can\'t fold).\n\n    Inputs: text - raw string. Outputs: cleaned lowercase string.\n    """\n    text = unicodedata.normalize("NFKC", text).casefold()\n    if text.isascii():\n        return text\n    text = text.translate(_LIGATURES).translate(_QUOTES)\n    text = unicodedata.normalize("NFKD", text)\n    text = _COMBINING_LATIN_RE.sub("", text)\n    return unicodedata.normalize("NFC", text)\n\n\ndef _join_initials(text: str) -> str:\n    """Join dotted single-letter initials: "s.b.i." -> "sbi", "o.d." -> "od".\n\n    Inputs: text - lowercase text. Outputs: text with initials joined.\n    """\n    return _INITIALS_RE.sub(lambda m: m.group(1).replace(".", "") + " ", text)\n\n\ndef _reduce_domain(token: str) -> str:\n    """Reduce a web-domain-looking token to its main label ("abc.com" -> "abc").\n\n    Inputs: token - one whitespace-free token.\n    Outputs: the label, or the token unchanged if it isn\'t a domain.\n    """\n    if "." not in token:\n        return token\n    m = _DOMAIN_RE.match(token)\n    return m.group(1) if m else token\n\n\ndef basic_clean(text: str) -> tuple[str, bool]:\n    """Full text normalisation shared by names and addresses (plan SS8.1 steps 1-5, 9).\n\n    Inputs: text - raw field value.\n    Outputs: (normalised text with single spaces, romanised flag).\n    """\n    text = _unicode_clean(text)\n    text, romanized = _romanize_text(text) if not text.isascii() else (text, False)\n    text = text.replace("&", " & ")\n    text = _URL_PREFIX_RE.sub("", text)\n    text = " ".join(_reduce_domain(t) for t in text.split())\n    text = _join_initials(text)\n    text = text.replace("\'", "")  # "macy\'s" -> "macys"\n    text = _NUM_SUFFIX_RE.sub(r"\\1\\2", text)  # "12 bis" -> "12bis"\n    text = _NON_WORD_RE.sub(" ", text)\n    tokens = []\n    for t in text.split():\n        if t in _NULL_TOKENS:\n            continue\n        tokens.append("&" if t in _CONNECTORS else t)\n    return " ".join(tokens), romanized\n\n\ndef fold(text: str) -> str:\n    """Phonetic/transliteration fold of already-normalised text (plan SS8.1 step 8).\n\n    Digit-bearing tokens are left unchanged.\n\n    Inputs: text - output of `basic_clean`. Outputs: folded text.\n    """\n    out = []\n    for t in text.split():\n        if not _DIGIT_RE.search(t):\n            for pat, rep in _FOLD_RULES:\n                t = pat.sub(rep, t)\n        out.append(t)\n    return " ".join(out)\n\n\ndef extract_landmark(segments: list[str]) -> tuple[list[str], str]:\n    """Move landmark phrases ("near X Y") out of normalised address segments.\n\n    The trigger plus up to 4 following tokens of the same comma segment are\n    removed. A trigger right after a house number is kept (it is probably a\n    street name such as "12 Near Road"; plan SS8.3).\n\n    Inputs: segments - list of normalised comma segments of one address.\n    Outputs: (segments without landmark phrases, landmark text).\n    """\n    landmark: list[str] = []\n    out_segments = []\n    for seg in segments:\n        toks = seg.split()\n        i = 0\n        kept: list[str] = []\n        while i < len(toks):\n            hit = None\n            for trig in _LANDMARK_TRIGGERS:\n                if tuple(toks[i : i + len(trig)]) == trig:\n                    hit = trig\n                    break\n            after_number = i > 0 and _DIGIT_RE.search(toks[i - 1]) is not None\n            if hit and not after_number and i + len(hit) < len(toks):\n                end = min(len(toks), i + len(hit) + _LANDMARK_MAX_TOKENS)\n                landmark.extend(toks[i:end])\n                i = end\n            else:\n                kept.append(toks[i])\n                i += 1\n        out_segments.append(" ".join(kept))\n    return out_segments, " ".join(landmark)\n\n\ndef number_tokens(text: str) -> list[str]:\n    """Return the digit-bearing tokens of normalised text, in order."""\n    return [t for t in text.split() if _DIGIT_RE.search(t)]\n\n\ndef postcode_candidates(segments: list[str], house_number: str) -> list[str]:\n    """Find postcode-shaped tokens by shape and position, never by country.\n\n    Candidates: 4-6 digit runs, or 2-4-char mixed letter+digit tokens, that\n    sit in the last two comma segments and are not the house number.\n\n    Inputs: segments - normalised comma segments; house_number - to exclude.\n    Outputs: list of candidate tokens (possibly empty).\n    """\n    cands = []\n    for seg in segments[-2:] if len(segments) > 1 else []:\n        for t in seg.split():\n            if t == house_number:\n                continue\n            if _POSTCODE_DIGITS_RE.match(t) or _POSTCODE_MIXED_RE.match(t):\n                cands.append(t)\n    return cands\n\n\ndef normalize_record(name: str, address: str) -> dict:\n    """Normalise one record\'s name and address into all derived fields.\n\n    Inputs: name, address - raw strings (may be empty).\n    Outputs: dict with keys norm_name, norm_addr, fold_name, fold_addr,\n    name_numbers, addr_numbers, house_number, postcodes, landmark,\n    name_romanized.\n    """\n    norm_name, name_rom = basic_clean(name)\n    # Addresses are normalised per comma segment so landmark and postcode\n    # rules can use segment boundaries.\n    segs = []\n    for seg in address.split(","):\n        s, _ = basic_clean(seg)\n        if s:\n            segs.append(s)\n    segs, landmark = extract_landmark(segs)\n    segs = [s for s in segs if s]\n    norm_addr = " ".join(segs)\n    addr_nums = number_tokens(norm_addr)\n    house = addr_nums[0] if addr_nums else ""\n    return {\n        "norm_name": norm_name,\n        "norm_addr": norm_addr,\n        "fold_name": fold(norm_name),\n        "fold_addr": fold(norm_addr),\n        "name_numbers": " ".join(number_tokens(norm_name)),\n        "addr_numbers": " ".join(addr_nums),\n        "house_number": house,\n        "postcodes": " ".join(postcode_candidates(segs, house)),\n        "landmark": landmark,\n        "name_romanized": name_rom,\n    }\n\n\n_OUT_COLS = [\n    "norm_name", "norm_addr", "fold_name", "fold_addr", "name_numbers",\n    "addr_numbers", "house_number", "postcodes", "landmark", "name_romanized",\n]\n\n\ndef _normalize_chunk(pairs: list[tuple[str, str]]) -> dict[str, list]:\n    """Worker: normalise a chunk of (name, address) pairs into column lists."""\n    cols: dict[str, list] = {c: [] for c in _OUT_COLS}\n    for name, addr in pairs:\n        rec = normalize_record(name, addr)\n        for c in _OUT_COLS:\n            cols[c].append(rec[c])\n    return cols\n\n\ndef normalize_df(\n    df: pd.DataFrame, source: str, n_jobs: int = 1, chunk: int = 50_000, log_every: int = 20\n) -> pd.DataFrame:\n    """Normalise a raw source DataFrame (S1/S2/S3) into the NB02 record schema.\n\n    Inputs: df - raw source frame (entity_id, business_name, business_address,\n            country); source - "S1"/"S2"/"S3"; n_jobs - worker processes;\n            chunk - records per worker task; log_every - log each N chunks.\n    Outputs: new DataFrame with entity_id, source, country, raw_name,\n    raw_addr, the `normalize_record` fields, and name_empty/addr_empty flags.\n    """\n    t0 = time.time()\n    pairs = list(zip(df["business_name"].tolist(), df["business_address"].tolist()))\n    chunks = [pairs[i : i + chunk] for i in range(0, len(pairs), chunk)]\n    cols: dict[str, list] = {c: [] for c in _OUT_COLS}\n\n    def _collect(i: int, part: dict[str, list]) -> None:\n        for c in _OUT_COLS:\n            cols[c].extend(part[c])\n        if (i + 1) % log_every == 0 or i + 1 == len(chunks):\n            print(\n                f"    normalize {source}: {min((i + 1) * chunk, len(pairs)):,}/{len(pairs):,} "\n                f"({time.time() - t0:.0f}s)",\n                flush=True,\n            )\n\n    if n_jobs > 1 and len(chunks) > 1:\n        with Pool(n_jobs) as pool:\n            for i, part in enumerate(pool.imap(_normalize_chunk, chunks)):\n                _collect(i, part)\n    else:\n        for i, c in enumerate(chunks):\n            _collect(i, _normalize_chunk(c))\n\n    out = pd.DataFrame(\n        {\n            "entity_id": df["entity_id"].to_numpy(),\n            "source": source,\n            "country": df["country"].to_numpy(),\n            "raw_name": df["business_name"].to_numpy(),\n            "raw_addr": df["business_address"].to_numpy(),\n            **cols,\n        }\n    )\n    out["name_empty"] = out["norm_name"].eq("")\n    out["addr_empty"] = out["norm_addr"].eq("")\n    return out\n\n\ndef main() -> None:\n    """CLI smoke test: normalise a few strings given on the command line."""\n    import sys\n\n    for s in sys.argv[1:] or ["S.B.I. Café & Co., near City Mall, 12 bis Rue X"]:\n        print(s, "->", normalize_record(s, s))\n\n\nif __name__ == "__main__":\n    main()\n'
normalize = types.ModuleType('normalize')
sys.modules['normalize'] = normalize
_corpus_stats_source = '"""Step 3 — corpus statistics: rarity (IDF), suffix-likeness, street-type-likeness.\n\nMaster plan SS9. Everything is computed from token counts of the records of\nthe current run (no labels): train stats from train files, test stats from\ntest files (`stats_mode: per_run`). If the organisers rule out test-time\nstatistics (memory.md Q3), `stats_mode: train_only` makes test reuse the\ntrain table (plan SS9.4).\n\nCounts are kept per country *label as found in the data* (open set, never a\nhard-coded value, CLAUDE.md SS3 rule 5); global counts are the sum.\n\nTable layout (`count_tokens` output, long format):\n    field     - which text field ("norm_name", "fold_name", "norm_addr", "fold_addr")\n    country   - country label, or "" for the global row\n    token     - the token\n    df        - number of records containing the token\n    pos_count - name fields: occurrences in the last 2 positions (suffix\n                position); address fields: occurrences 1-3 tokens after the\n                house number (street-type position)\n    n_docs    - records in that (field, country) group (repeated per row)\nTokens with global df < 2 are dropped to save space; a missing token is\ntreated as df = 1 by the lookup helpers.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport math\n\nimport numpy as np\nimport pandas as pd\n\nlog = logging.getLogger(__name__)\n\nNAME_FIELDS = ("norm_name", "fold_name")\nADDR_FIELDS = ("norm_addr", "fold_addr")\n_TYPE_WINDOW = 3  # street-type position = 1..3 tokens after the house number\n\n\ndef _explode_tokens(texts: pd.Series) -> pd.DataFrame:\n    """Split texts into one row per token with its position and the text length.\n\n    Inputs: texts - Series of space-separated token strings (any index).\n    Outputs: DataFrame with columns row (int position of the record), token,\n    pos (0-based token position), n_tok (tokens in that record).\n    """\n    lists = texts.reset_index(drop=True).str.split()\n    lens = lists.str.len().fillna(0).astype(np.int32)\n    ex = lists.explode()\n    ex = ex[ex.notna()]\n    rows = ex.index.to_numpy()\n    out = pd.DataFrame({"row": rows, "token": ex.to_numpy()})\n    out["pos"] = out.groupby("row").cumcount().astype(np.int32)\n    out["n_tok"] = lens.to_numpy()[rows]\n    return out\n\n\ndef count_field(df: pd.DataFrame, field: str) -> pd.DataFrame:\n    """Count df and positional occurrences of every token of one field, per country.\n\n    Inputs: df - normalised records (needs `country`, `field`, and for address\n            fields also `house_number`); field - column name.\n    Outputs: DataFrame (country, token, df, pos_count) for this frame.\n    """\n    ex = _explode_tokens(df[field])\n    ex["country"] = df["country"].to_numpy()[ex["row"].to_numpy()]\n    if field in NAME_FIELDS:\n        pos_hit = ex["pos"] >= ex["n_tok"] - 2\n    else:\n        # First digit-bearing token\'s position per record = house number position.\n        is_num = ex["token"].str.contains(r"\\d", regex=True)\n        first_num = ex[is_num].groupby("row")["pos"].min()\n        hpos = ex["row"].map(first_num)\n        delta = ex["pos"] - hpos\n        pos_hit = (delta >= 1) & (delta <= _TYPE_WINDOW) & ~is_num\n    ex["pos_hit"] = pos_hit.fillna(False).astype(np.int32)\n    # df counts a token once per record; pos_count counts every positional hit.\n    dedup = ex.drop_duplicates(["row", "token"])\n    dfc = dedup.groupby(["country", "token"], sort=False).size().rename("df")\n    posc = ex.groupby(["country", "token"], sort=False)["pos_hit"].sum().rename("pos_count")\n    return pd.concat([dfc, posc], axis=1).reset_index()\n\n\nclass TokenCounter:\n    """Incremental version of the token-statistics count (one frame at a time).\n\n    Lets NB02 count one source (millions of rows) and free it before loading\n    the next, instead of holding all sources in memory. Call `add(frame)` per\n    record frame, then `finalize()` for the long table (module docstring).\n    """\n\n    def __init__(self, fields=NAME_FIELDS + ADDR_FIELDS, min_df: int = 2):\n        """Inputs: fields - text fields to count; min_df - global df cut-off."""\n        self.fields = tuple(fields)\n        self.min_df = min_df\n        self.acc: dict[str, pd.DataFrame | None] = {f: None for f in self.fields}\n        self.n_docs: dict[str, int] = {}\n\n    def add(self, frame: pd.DataFrame) -> None:\n        """Add the counts of one normalised record frame (needs country + fields)."""\n        for field in self.fields:\n            c = count_field(frame, field)\n            prev = self.acc[field]\n            self.acc[field] = (\n                c if prev is None\n                else pd.concat([prev, c]).groupby(["country", "token"], sort=False).sum().reset_index()\n            )\n        for k, v in frame["country"].value_counts().items():\n            self.n_docs[k] = self.n_docs.get(k, 0) + int(v)\n\n    def finalize(self) -> pd.DataFrame:\n        """Return the long table (field, country, token, df, pos_count, n_docs)."""\n        n_docs = dict(self.n_docs)\n        n_docs[""] = sum(self.n_docs.values())\n        parts = []\n        for field in self.fields:\n            acc = self.acc[field]\n            glob = acc.groupby("token", sort=False)[["df", "pos_count"]].sum().reset_index()\n            glob = glob[glob["df"] >= self.min_df]\n            glob["country"] = ""\n            local = acc[acc["token"].isin(set(glob["token"]))]\n            tab = pd.concat([glob, local], ignore_index=True)\n            tab["n_docs"] = tab["country"].map(n_docs).astype(np.int64)\n            tab["field"] = field\n            parts.append(tab[["field", "country", "token", "df", "pos_count", "n_docs"]])\n            print(f"    stats {field}: {len(glob):,} tokens with df>={self.min_df}", flush=True)\n        return pd.concat(parts, ignore_index=True)\n\n\ndef count_tokens(frames: list[pd.DataFrame], fields=NAME_FIELDS + ADDR_FIELDS, min_df: int = 2) -> pd.DataFrame:\n    """Build the long-format token statistics table over several record frames.\n\n    Inputs: frames - normalised record frames of one run (e.g. S1, S2, S3 of\n            train); fields - text fields to count; min_df - drop tokens whose\n            global df is below this.\n    Outputs: long table (field, country, token, df, pos_count, n_docs); see\n    module docstring. Global rows have country "".\n    """\n    counter = TokenCounter(fields, min_df)\n    for f in frames:\n        counter.add(f)\n    return counter.finalize()\n\n\ndef idf(df: np.ndarray | float, n_docs: int) -> np.ndarray | float:\n    """Smoothed IDF: log((N + 1) / (df + 1)) + 1 (master plan SS9.1)."""\n    return np.log((n_docs + 1) / (np.asarray(df) + 1)) + 1\n\n\ndef idf_lookup(stats: pd.DataFrame, field: str, country: str = "") -> tuple[dict[str, float], float]:\n    """Token -> IDF dict for one field and country group ("" = global).\n\n    Inputs: stats - `count_tokens` table; field; country.\n    Outputs: (dict token -> idf, default idf for an unseen token, i.e. df = 1).\n    """\n    sub = stats[(stats["field"] == field) & (stats["country"] == country)]\n    if sub.empty:\n        return {}, 1.0\n    n = int(sub["n_docs"].iloc[0])\n    return dict(zip(sub["token"], idf(sub["df"].to_numpy(), n))), float(idf(1, n))\n\n\ndef _likeness(sub: pd.DataFrame) -> pd.Series:\n    """pos_ratio x sigmoid(z-scored log frequency), shared by suffix/street-type scores.\n\n    Inputs: sub - global rows of one field (token, df, pos_count, n_docs).\n    Outputs: Series of scores in [0, 1] indexed like `sub`.\n    """\n    ratio = (sub["pos_count"] / sub["df"].clip(lower=1)).clip(upper=1.0)\n    logf = np.log(sub["df"] / sub["n_docs"])\n    mu, sd = float(logf.mean()), float(logf.std() or 1.0)\n    return ratio * (1.0 / (1.0 + np.exp(-(logf - mu) / sd)))\n\n\ndef suffix_likeness(stats: pd.DataFrame, field: str = "norm_name") -> dict[str, float]:\n    """Suffix-likeness per name token: end-position ratio x frequency sigmoid (plan SS9.2).\n\n    High for tokens that are frequent AND almost always at the end of a name\n    (legal forms, generic end words). Inputs: stats table; name field.\n    Outputs: dict token -> score in [0, 1].\n    """\n    sub = stats[(stats["field"] == field) & (stats["country"] == "")]\n    return dict(zip(sub["token"], _likeness(sub)))\n\n\ndef street_type_likeness(stats: pd.DataFrame, field: str = "norm_addr") -> dict[str, float]:\n    """Street-type-likeness per address token (plan SS9.3), same formula as suffixes.\n\n    Inputs: stats table; address field. Outputs: dict token -> score in [0, 1].\n    """\n    sub = stats[(stats["field"] == field) & (stats["country"] == "")]\n    return dict(zip(sub["token"], _likeness(sub)))\n\n\ndef top_tokens(stats: pd.DataFrame, field: str, n: int = 50, by: str = "df") -> list[tuple[str, float]]:\n    """Top-n global tokens of a field by df (or by a likeness score), for sanity printouts.\n\n    Inputs: stats; field; n; by - "df", "suffix" or "street".\n    Outputs: list of (token, value).\n    """\n    if by == "df":\n        sub = stats[(stats["field"] == field) & (stats["country"] == "")].nlargest(n, "df")\n        return list(zip(sub["token"], sub["df"].astype(float)))\n    scores = suffix_likeness(stats, field) if by == "suffix" else street_type_likeness(stats, field)\n    return sorted(scores.items(), key=lambda kv: -kv[1])[:n]\n\n\ndef main() -> None:\n    """Smoke test: count tokens of a few hand-made records and print top suffixes."""\n    from . import normalize\n\n    raw = pd.DataFrame(\n        {\n            "entity_id": [f"S1-{i}" for i in range(4)],\n            "business_name": ["Alpha Pvt Ltd", "Beta Pvt Ltd", "Gamma Ltd", "Delta Inc"],\n            "business_address": ["1 Main Road, X", "2 Hill Road, Y", "3 Main Street, Z", "4 Oak Street, W"],\n            "country": ["C1", "C1", "C2", "C2"],\n        }\n    )\n    stats = count_tokens([normalize.normalize_df(raw, "S1")], min_df=1)\n    print(top_tokens(stats, "norm_name", 5, by="suffix"))\n    print(top_tokens(stats, "norm_addr", 5, by="street"))\n    print(math.isfinite(idf(1, 4)))\n\n\nif __name__ == "__main__":\n    main()\n'
corpus_stats = types.ModuleType('corpus_stats')
sys.modules['corpus_stats'] = corpus_stats
_blocking_source = '"""Step 6 — candidate generation (blocking), master plan SS12.\n\nChannels (all restricted to equal country labels — EDA E5 found 0 cross-\ncountry matches — by label equality only, never by value):\n- dense       S1 -> pool top-k from NB03 (frozen) or NB04 (fine-tuned) vectors\n- reverse     pool -> S1 top-rk from the same run (keeps pairs whose S1 is\n              crowded by near neighbours)\n- name_char   char_wb 3-4-gram TF-IDF on the normalised name\n- addr_char   char_wb 3-4-gram TF-IDF on the normalised address\n- name_tok    rare-token key: word tokens of norm + fold name (typo- and\n              transliteration-tolerant via the fold form), IDF-weighted\n- num_key     house number + first street token ("35840_chester"); stands in\n              for the plan\'s postcode key, since NB02 found postcodes in only\n              ~1-2% of records while house numbers are in ~90%\n- name_pair   unordered pairs of fold-form name tokens ("glypheus|platforms")\n- addr_pair   unordered pairs of fold-form address tokens ("238|houston")\n- cross_pair  name token x address token pairs ("glypheus|houston"): keeps a\n              match whose name is broken (native script, concatenation) or\n              generic while part of the address survives, and vice versa\n              Names and addresses here are combinations of individually\n              common words (NB05 sparse v1: "Glypheus" starts many unrelated\n              names), so single tokens / char n-grams are pruned by the df cap\n              while their pairs stay rare. A typo breaks only the pairs that\n              contain the typo\'d token.\n\nAll sparse channels share one mechanism (`sparse_topk`): hashed features ->\nTF-IDF (sublinear tf, smoothed idf, L2 rows) -> chunked sparse product ->\ntop-k per query. Index-side features with df above `max_df` are dropped\nbefore the product (they carry little identity and dominate the cost); the\nscores are then partial cosines, fine for ranking.\n\nThe union is pruned to `prune_top` per S1 by a small LightGBM pre-ranker\ntrained on Half A labels (cheap vectorised features: channel scores/ranks,\ndense cosine, gaps to the S1\'s best). The pruned set is what later stages\nscore, i.e. `candidate_pairs.tsv` (up to the scale-guard cut in NB06).\n"""\n\nfrom __future__ import annotations\n\nimport time\nimport multiprocessing\nimport re\n\nimport numpy as np\nimport pandas as pd\nimport scipy.sparse as sp\n\nCHANNELS = ["dense", "reverse", "name_char", "addr_char", "name_tok", "num_key", "name_pair", "addr_pair", "cross_pair"]\n_PAIR_MAX_TOKENS = {"name_pair": 8, "addr_pair": 10, "cross_name": 6, "cross_addr": 10}\n# Digits used as look-alike letters inside words ("k01kata", "h0spital",\n# "dermato1ogy"): a noise type found in NB05 v4\'s missed B pairs.\n_NUMBER_LIKE = re.compile(r"^\\d+[a-z]{0,4}$")\n_DELEET = str.maketrans({"0": "o", "1": "l", "3": "e", "4": "a", "5": "s", "7": "t", "8": "b"})\n\n\ndef deleet(token: str) -> str:\n    """Map look-alike digits to letters in a mostly-alphabetic token; other tokens unchanged.\n\n    "k01kata" -> "kolkata", "8ombay" -> "bombay"; "238", "3rd", "12bis", "b2" stay.\n    """\n    n_dig = sum(ch.isdigit() for ch in token)\n    # Digits-then-short-suffix tokens are numbers: ordinals ("3rd"), house numbers ("12b", "12bis").\n    if n_dig == 0 or n_dig * 2 >= len(token) or _NUMBER_LIKE.match(token):\n        return token\n    return token.translate(_DELEET)\n\n\ndef _tokens(text: str) -> list[str]:\n    """Whitespace tokens with look-alike digits mapped back to letters."""\n    return [deleet(t) for t in text.split()]\n_BIT = {c: 1 << i for i, c in enumerate(CHANNELS)}\n\n# ---------------------------------------------------------------------------\n# Per-record channel texts\n# ---------------------------------------------------------------------------\n\n\ndef name_tok_text(norm_name: pd.Series, fold_name: pd.Series) -> list[str]:\n    """Token text for the rare-token channel: norm tokens + \'~\'-prefixed fold tokens.\n\n    Digit-only tokens are dropped (numbers are compared elsewhere).\n    Inputs: norm_name, fold_name - aligned Series. Outputs: list of strings.\n    """\n    out = []\n    for n, f in zip(norm_name.tolist(), fold_name.tolist()):\n        toks = [t for t in _tokens(n) if not t.isdigit() and t != "&"]\n        toks += ["~" + t for t in _tokens(f) if not t.isdigit() and t != "&" and t not in toks]\n        out.append(" ".join(toks))\n    return out\n\n\ndef num_key_text(norm_addr: pd.Series, house_number: pd.Series) -> list[str]:\n    """"<house number>_<first non-number token after it>" key per record, or "".\n\n    Inputs: norm_addr, house_number - aligned Series. Outputs: list of keys.\n    """\n    out = []\n    for a, h in zip(norm_addr.tolist(), house_number.tolist()):\n        key = ""\n        if h:\n            toks = a.split()\n            try:\n                i = toks.index(h)\n            except ValueError:\n                i = -1\n            for t in toks[i + 1 :]:\n                if not any(ch.isdigit() for ch in t):\n                    key = f"{h}_{t}"\n                    break\n        out.append(key)\n    return out\n\n\ndef _fork_pool(n_jobs: int):\n    """A fork-based process pool, or None where fork is unavailable (Windows: run in-process).\n\n    Fork lets workers share the big matrices set in module globals without\n    pickling them.\n    """\n    if n_jobs > 1 and "fork" in multiprocessing.get_all_start_methods():\n        return multiprocessing.get_context("fork").Pool(n_jobs)\n    return None\n\n\ndef _pair_keys(text: str, max_tokens: int) -> list[str]:\n    """Unordered pairs of the first `max_tokens` distinct tokens of a text ("a|b", a < b).\n\n    Order-free, so reordered records share the same keys.\n    """\n    toks = sorted(set(_tokens(text)[: max_tokens * 2]))[:max_tokens]\n    return [a + "|" + b for i, a in enumerate(toks) for b in toks[i + 1 :]]\n\n\ndef _name_pair_analyzer(text: str) -> list[str]:\n    """Analyzer for the name_pair channel (module-level so workers can build it)."""\n    return _pair_keys(text, _PAIR_MAX_TOKENS["name_pair"])\n\n\ndef _addr_pair_analyzer(text: str) -> list[str]:\n    """Analyzer for the addr_pair channel."""\n    return _pair_keys(text, _PAIR_MAX_TOKENS["addr_pair"])\n\n\ndef _cross_pair_analyzer(text: str) -> list[str]:\n    """Analyzer for the cross_pair channel: text is "<fold name>\t<fold address>"."""\n    name, _, addr = text.partition("\t")\n    nt = sorted({t for t in _tokens(name) if not t.isdigit() and t != "&"})[: _PAIR_MAX_TOKENS["cross_name"]]\n    at = sorted(set(_tokens(addr)))[: _PAIR_MAX_TOKENS["cross_addr"]]\n    return [f"{a}^{b}" for a in nt for b in at]\n\n\ndef cross_text(fold_name: pd.Series, fold_addr: pd.Series) -> list[str]:\n    """Per-record input text for the cross_pair channel."""\n    return [f"{n}\t{a}" if a else "" for n, a in zip(fold_name.tolist(), fold_addr.tolist())]\n\n\n# ---------------------------------------------------------------------------\n# Hashed TF-IDF matrices\n# ---------------------------------------------------------------------------\n_N_FEATURES = 2**22\n\n\ndef _vectorizer(kind: str):\n    """HashingVectorizer for a channel kind ("char", "word", "name_pair", "addr_pair")."""\n    from sklearn.feature_extraction.text import HashingVectorizer\n\n    if kind == "char":\n        return HashingVectorizer(\n            analyzer="char_wb", ngram_range=(3, 4), n_features=_N_FEATURES,\n            alternate_sign=False, norm=None, dtype=np.float32, lowercase=False,\n        )\n    analyzer = {"word": str.split, "name_pair": _name_pair_analyzer, "addr_pair": _addr_pair_analyzer,\n                "cross_pair": _cross_pair_analyzer}[kind]\n    return HashingVectorizer(\n        analyzer=analyzer, n_features=_N_FEATURES, alternate_sign=False, norm=None, dtype=np.float32, lowercase=False,\n    )\n\n\ndef _hash_chunk(args):\n    """Worker: hash one chunk of texts."""\n    kind, texts = args\n    return _vectorizer(kind).transform(texts)\n\n\ndef hashed_counts(texts: list[str], kind: str, n_jobs: int = 1, chunk: int = 200_000) -> sp.csr_matrix:\n    """Term-count matrix of texts with the channel\'s hashing vectorizer (parallel).\n\n    Inputs: texts; kind - "char"/"word"/"name_pair"/"addr_pair"; n_jobs; chunk - texts per task.\n    Outputs: csr_matrix [len(texts), 2**22] float32 counts.\n    """\n    parts = [(kind, texts[i : i + chunk]) for i in range(0, len(texts), chunk)]\n    if not parts:\n        return sp.csr_matrix((0, _N_FEATURES), dtype=np.float32)\n    pool = _fork_pool(n_jobs) if len(parts) > 1 else None\n    if pool is not None:\n        with pool:\n            mats = pool.map(_hash_chunk, parts)\n    else:\n        mats = [_hash_chunk(p) for p in parts]\n    return sp.vstack(mats).tocsr()\n\n\ndef _l2_rows(m: sp.csr_matrix) -> None:\n    """L2-normalise csr rows in place (empty rows stay empty)."""\n    # bincount over row ids, not np.add.reduceat: reduceat fails when trailing\n    # rows are empty (NB05 sparse v1 crashed on empty addresses at the end).\n    counts = np.diff(m.indptr)\n    rows = np.repeat(np.arange(m.shape[0]), counts)\n    sq = np.bincount(rows, weights=m.data.astype(np.float64) ** 2, minlength=m.shape[0])\n    norms = np.where(sq > 0, np.sqrt(sq), 1.0)\n    m.data /= norms[rows].astype(np.float32)\n\n\ndef tfidf_pair(q_counts: sp.csr_matrix, p_counts: sp.csr_matrix, max_df: int) -> tuple[sp.csr_matrix, sp.csr_matrix]:\n    """TF-IDF weight query and pool counts with shared df; prune frequent pool features.\n\n    idf = log((N+1)/(df+1)) + 1 over query + pool rows; tf = 1 + log(count);\n    rows L2-normalised; then pool columns with df > max_df are removed.\n\n    Inputs: q_counts, p_counts - hashed count matrices; max_df - index cap.\n    Outputs: (Q weighted, P weighted and pruned), both csr float32.\n    """\n    df = np.bincount(p_counts.indices, minlength=_N_FEATURES) + np.bincount(q_counts.indices, minlength=_N_FEATURES)\n    n = q_counts.shape[0] + p_counts.shape[0]\n    idf = (np.log((n + 1) / (df + 1)) + 1).astype(np.float32)\n    out = []\n    for m in (q_counts, p_counts):\n        m = m.copy()\n        m.data = (1 + np.log(m.data)) * idf[m.indices]\n        _l2_rows(m)\n        out.append(m)\n    q, p = out\n    keep = (df <= max_df)[p.indices]\n    p.data = p.data * keep\n    p.eliminate_zeros()\n    return q, p\n\n\n# ---------------------------------------------------------------------------\n# Chunked sparse top-k\n# ---------------------------------------------------------------------------\n_G: dict = {}  # worker globals (inherited through fork)\n\n\ndef _topk_rows(start: int, end: int):\n    """Worker: top-k pool rows for query rows [start, end) of _G[\'Q\'] against _G[\'PT\']."""\n    r = (_G["Q"][start:end] @ _G["PT"]).tocsr()\n    k = _G["k"]\n    qi, pi, sc, rk = [], [], [], []\n    for row in range(r.shape[0]):\n        a, b = r.indptr[row], r.indptr[row + 1]\n        if a == b:\n            continue\n        d, ix = r.data[a:b], r.indices[a:b]\n        if b - a > k:\n            sel = np.argpartition(-d, k)[:k]\n            d, ix = d[sel], ix[sel]\n        order = np.argsort(-d, kind="stable")\n        qi.append(np.full(len(order), start + row, dtype=np.int32))\n        pi.append(ix[order].astype(np.int32))\n        sc.append(d[order].astype(np.float32))\n        rk.append(np.arange(len(order), dtype=np.int16))\n    if not qi:\n        return (np.empty(0, np.int32),) * 2 + (np.empty(0, np.float32), np.empty(0, np.int16))\n    return np.concatenate(qi), np.concatenate(pi), np.concatenate(sc), np.concatenate(rk)\n\n\ndef _topk_task(bounds):\n    """Pool.map adapter for `_topk_rows`."""\n    return _topk_rows(*bounds)\n\n\ndef sparse_topk(q: sp.csr_matrix, p: sp.csr_matrix, k: int, n_jobs: int = 1, chunk: int = 1000):\n    """Top-k pool rows per query row by sparse dot product.\n\n    Inputs: q [nq, F], p [np, F] csr (already weighted/normalised); k;\n            n_jobs - fork workers (1 = in-process, used by tests/Windows);\n            chunk - query rows per task.\n    Outputs: (q_row, p_row, score, rank) arrays; rank 0 = best.\n    """\n    _G.update(Q=q, PT=p.T.tocsr(), k=k)\n    bounds = [(s, min(s + chunk, q.shape[0])) for s in range(0, q.shape[0], chunk)]\n    pool = _fork_pool(n_jobs) if len(bounds) > 1 else None\n    if pool is not None:\n        with pool:\n            parts = pool.map(_topk_task, bounds, chunksize=4)\n    else:\n        parts = [_topk_task(b) for b in bounds]\n    _G.clear()\n    parts = [x for x in parts if len(x[0])]\n    if not parts:\n        return np.empty(0, np.int32), np.empty(0, np.int32), np.empty(0, np.float32), np.empty(0, np.int16)\n    return tuple(np.concatenate([x[i] for x in parts]) for i in range(4))\n\n\ndef run_sparse_channel(q_texts: list[str], p_texts: list[str], kind: str, k: int, max_df: int, n_jobs: int = 1):\n    """Hash + TF-IDF + top-k for one channel within one country group.\n\n    Inputs: query/pool channel texts; kind "char"/"word"; k; max_df; n_jobs.\n    Outputs: (q_row, p_row, score, rank) local to the given lists.\n    """\n    qc = hashed_counts(q_texts, kind, n_jobs)\n    pc = hashed_counts(p_texts, kind, n_jobs)\n    q, p = tfidf_pair(qc, pc, max_df)\n    del qc, pc\n    return sparse_topk(q, p, k, n_jobs)\n\n\n# ---------------------------------------------------------------------------\n# Union of channels + cheap features\n# ---------------------------------------------------------------------------\n\n\ndef union_channels(parts: dict[str, tuple], n_pool: int) -> pd.DataFrame:\n    """Merge per-channel (q_row, p_row, score, rank) lists into one row per pair.\n\n    Inputs: parts - {channel: (q_row, p_row, score, rank)} with global rows;\n            n_pool - pool size (for the int64 pair key).\n    Outputs: DataFrame sorted by (q_row, p_row) with q_row, p_row, bitmask,\n    n_channels, and <channel>_score / <channel>_rank (NaN / 999 when absent).\n    """\n    keys = {c: v[0].astype(np.int64) * n_pool + v[1].astype(np.int64) for c, v in parts.items()}\n    allk = np.unique(np.concatenate(list(keys.values()))) if keys else np.empty(0, np.int64)\n    out = pd.DataFrame({"q_row": (allk // n_pool).astype(np.int32), "p_row": (allk % n_pool).astype(np.int32)})\n    bitmask = np.zeros(len(allk), dtype=np.int16)\n    for c in CHANNELS:\n        score = np.full(len(allk), np.nan, dtype=np.float32)\n        rank = np.full(len(allk), 999, dtype=np.int16)\n        if c in keys and len(keys[c]):\n            # A channel can list a pair twice only through a bug; keep the best rank.\n            kk, first = np.unique(keys[c], return_index=True)\n            pos = np.searchsorted(allk, kk)\n            score[pos] = parts[c][2][first]\n            rank[pos] = parts[c][3][first]\n            bitmask[pos] |= _BIT[c]\n        out[f"{c}_score"] = score\n        out[f"{c}_rank"] = rank\n    out["bitmask"] = bitmask\n    out["n_channels"] = np.array([bin(b).count("1") for b in range(1 << len(CHANNELS))], dtype=np.int8)[bitmask]\n    return out\n\n\ndef add_dense_cos(u: pd.DataFrame, q_emb: np.ndarray, p_emb: np.ndarray, chunk: int = 1_000_000) -> None:\n    """Add `dense_cos` (embedding dot product) for every union pair, in place, chunked."""\n    cos = np.empty(len(u), dtype=np.float32)\n    qr, pr = u["q_row"].to_numpy(), u["p_row"].to_numpy()\n    for s in range(0, len(u), chunk):\n        a = q_emb[qr[s : s + chunk]].astype(np.float32)\n        b = p_emb[pr[s : s + chunk]].astype(np.float32)\n        cos[s : s + chunk] = np.einsum("ij,ij->i", a, b)\n    u["dense_cos"] = cos\n\n\ndef add_gap_features(u: pd.DataFrame) -> None:\n    """Add per-S1 relative features (score minus the S1\'s best), in place.\n\n    Requires `u` sorted by q_row (as `union_channels` returns it).\n    """\n    starts = np.flatnonzero(np.r_[True, u["q_row"].to_numpy()[1:] != u["q_row"].to_numpy()[:-1]])\n    sizes = np.diff(np.r_[starts, len(u)])\n    for col in ("dense_cos", "name_char_score", "addr_char_score", "name_tok_score", "name_pair_score", "addr_pair_score",\n                "cross_pair_score"):\n        v = u[col].to_numpy()\n        best = np.fmax.reduceat(np.nan_to_num(v, nan=-1.0), starts)\n        u[f"{col}_gap"] = v - np.repeat(best, sizes)\n    u["union_size"] = np.repeat(sizes, sizes).astype(np.int16)\n\n\nPRUNE_FEATURES = [\n    "dense_cos", "dense_cos_gap", "dense_rank", "reverse_rank", "reverse_score",\n    "name_char_score", "name_char_rank", "name_char_score_gap",\n    "addr_char_score", "addr_char_rank", "addr_char_score_gap",\n    "name_tok_score", "name_tok_rank", "name_tok_score_gap",\n    "num_key_score", "n_channels", "union_size",\n    "name_pair_score", "name_pair_rank", "name_pair_score_gap",\n    "addr_pair_score", "addr_pair_rank", "addr_pair_score_gap",\n    "cross_pair_score", "cross_pair_rank", "cross_pair_score_gap",\n]\n\n\ndef train_pruner(u: pd.DataFrame, y: np.ndarray, seed: int = 42, max_rows: int = 3_000_000):\n    """Fit the cheap LightGBM pre-ranker on (Half A) union pairs.\n\n    Inputs: u - union frame with PRUNE_FEATURES; y - 0/1 labels; seed;\n            max_rows - subsample cap for speed.\n    Outputs: trained lightgbm.Booster.\n    """\n    import lightgbm as lgb\n\n    idx = np.arange(len(u))\n    if len(idx) > max_rows:\n        idx = np.random.default_rng(seed).choice(idx, max_rows, replace=False)\n        idx.sort()\n    params = {\n        "objective": "binary", "learning_rate": 0.1, "num_leaves": 31, "min_data_in_leaf": 100,\n        "feature_fraction": 0.9, "bagging_fraction": 0.8, "bagging_freq": 1, "seed": seed,\n        "bagging_seed": seed, "feature_fraction_seed": seed, "deterministic": True, "verbose": -1,\n    }\n    ds = lgb.Dataset(u[PRUNE_FEATURES].iloc[idx].to_numpy(np.float32), label=y[idx], feature_name=PRUNE_FEATURES)\n    return lgb.train(params, ds, num_boost_round=150)\n\n\ndef prune(u: pd.DataFrame, score: np.ndarray, top: int) -> pd.DataFrame:\n    """Keep the `top` highest-scoring pairs per S1 (ties broken by pool row).\n\n    Inputs: u - union frame; score - pre-ranker score per row; top.\n    Outputs: pruned frame (sorted by q_row, score desc) with `cheap_score`.\n    """\n    u = u.assign(cheap_score=score.astype(np.float32))\n    order = np.lexsort((u["p_row"].to_numpy(), -u["cheap_score"].to_numpy(), u["q_row"].to_numpy()))\n    u = u.iloc[order]\n    q = u["q_row"].to_numpy()\n    starts = np.flatnonzero(np.r_[True, q[1:] != q[:-1]])\n    rank = np.arange(len(u)) - np.repeat(starts, np.diff(np.r_[starts, len(u)]))\n    return u[rank < top].reset_index(drop=True)\n\n\n# ---------------------------------------------------------------------------\n# Blocking report (plan SS12.3)\n# ---------------------------------------------------------------------------\n\n\ndef blocking_report(\n    union: pd.DataFrame, pruned: pd.DataFrame, true_keys: np.ndarray, q_rows: np.ndarray, q_country: np.ndarray,\n    n_true_by_q: np.ndarray, n_pool: int, n_pool_total: int,\n) -> dict:\n    """Pair recall, entity-complete recall, RR, candidates/S1 and per-channel unique contribution.\n\n    Inputs: union/pruned - candidate frames (q_row, p_row, bitmask); true_keys -\n            sorted int64 keys q_row*n_pool+p_row of all true pairs of the\n            queried S1s; q_rows - queried S1 rows; q_country - their country\n            labels; n_true_by_q - true-match count per queried S1 (aligned to\n            q_rows); n_pool - key base; n_pool_total - pool size for RR.\n    Outputs: nested dict, overall and per country.\n    """\n    def _is_true(df):\n        k = df["q_row"].to_numpy().astype(np.int64) * n_pool + df["p_row"].to_numpy()\n        return np.isin(k, true_keys)\n\n    country_of = pd.Series(q_country, index=q_rows)\n    ntrue_of = pd.Series(n_true_by_q, index=q_rows)\n    u_true = _is_true(union)\n    p_true = _is_true(pruned)\n\n    def _one(sel_q: np.ndarray) -> dict:\n        qs = set(sel_q.tolist())\n        um = union["q_row"].isin(qs).to_numpy()\n        pm = pruned["q_row"].isin(qs).to_numpy()\n        n_true = int(ntrue_of.loc[sel_q].sum())\n        found = pd.Series(p_true[pm]).groupby(pruned["q_row"].to_numpy()[pm]).sum()\n        need = ntrue_of.loc[sel_q]\n        need = need[need > 0]\n        complete = (found.reindex(need.index).fillna(0).to_numpy() == need.to_numpy()).mean() if len(need) else 1.0\n        cps = pruned.loc[pm].groupby("q_row").size().reindex(sel_q).fillna(0)\n        uni = {}\n        bm_true = union.loc[um & u_true, "bitmask"].to_numpy()\n        for c, bit in _BIT.items():\n            uni[c] = {\n                "found": int(((bm_true & bit) > 0).sum()),\n                "unique": int((bm_true == bit).sum()),\n            }\n        return {\n            "n_s1": int(len(sel_q)),\n            "n_true_pairs": n_true,\n            "pair_recall_union": round(float(u_true[um].sum() / max(n_true, 1)), 5),\n            "pair_recall": round(float(p_true[pm].sum() / max(n_true, 1)), 5),\n            "entity_complete_recall": round(float(complete), 5),\n            "reduction_ratio": round(1 - float(pm.sum()) / max(len(sel_q) * n_pool_total, 1), 8),\n            "cands_per_s1_mean": round(float(cps.mean()), 2),\n            "cands_per_s1_p95": float(np.quantile(cps, 0.95)) if len(cps) else 0.0,\n            "union_per_s1_mean": round(float(um.sum() / max(len(sel_q), 1)), 2),\n            "channels": uni,\n        }\n\n    rep = {"ALL": _one(q_rows)}\n    for c in sorted(set(q_country.tolist())):\n        rep[c] = _one(q_rows[q_country == c])\n    return rep\n\n\ndef main() -> None:\n    """Smoke test: one sparse channel on four toy names."""\n    q = ["alpha trading co", "beta foods"]\n    p = ["alpha tradng company", "gamma foods", "beta food"]\n    print(run_sparse_channel(q, p, "char", k=2, max_df=10))\n\n\nif __name__ == "__main__":\n    main()\n'
blocking = types.ModuleType('blocking')
sys.modules['blocking'] = blocking
_explain_diff_source = '"""Explain-the-difference features (master plan SS13).\n\nFor one field (name or address) of a record pair, every token is either\n*explained* by a token (or token span) on the other side through a typed\nrelation (exact, fold, typo, abbreviation, split/join, initialism, number\nequality), or *unexplained*. Rare unexplained content words are the main\nnegative signal; the relation counts tell the model what kind of noise\nseparates the two records. Everything is language-free: relations are tests\non letters and positions, never word lists.\n\nPure Python (rapidfuzz is used for edit distances when installed, with a\nstdlib fallback so the module also runs without it). Token relations are\ncached per process because the vocabulary is small relative to the number of\npairs (memory.md E13).\n"""\n\nfrom __future__ import annotations\n\nimport re\n\n\ndef _py_dl(a: str, b: str) -> int:\n    """Optimal-string-alignment Damerau-Levenshtein distance (stdlib fallback)."""\n    prev2, prev = None, list(range(len(b) + 1))\n    for i in range(1, len(a) + 1):\n        cur = [i] + [0] * len(b)\n        for j in range(1, len(b) + 1):\n            cost = a[i - 1] != b[j - 1]\n            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)\n            if prev2 is not None and i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:\n                cur[j] = min(cur[j], prev2[j - 2] + 1)\n        prev2, prev = prev, cur\n    return prev[len(b)]\n\n\ndef _py_jw(a: str, b: str) -> float:\n    """Jaro-Winkler similarity (stdlib fallback, prefix scale 0.1, max prefix 4)."""\n    if a == b:\n        return 1.0\n    la, lb = len(a), len(b)\n    if not la or not lb:\n        return 0.0\n    win = max(max(la, lb) // 2 - 1, 0)\n    ma, mb = [False] * la, [False] * lb\n    m = 0\n    for i, ch in enumerate(a):\n        for j in range(max(0, i - win), min(lb, i + win + 1)):\n            if not mb[j] and b[j] == ch:\n                ma[i] = mb[j] = True\n                m += 1\n                break\n    if not m:\n        return 0.0\n    sa = [a[i] for i in range(la) if ma[i]]\n    sb = [b[j] for j in range(lb) if mb[j]]\n    t = sum(x != y for x, y in zip(sa, sb)) / 2\n    jaro = (m / la + m / lb + (m - t) / m) / 3\n    p = 0\n    while p < min(4, la, lb) and a[p] == b[p]:\n        p += 1\n    return jaro + p * 0.1 * (1 - jaro)\n\n\n_DIST: tuple | None = None\n\n\ndef _distances() -> tuple:\n    """(damerau_levenshtein, jaro_winkler) functions: rapidfuzz (C++) if importable, else the stdlib fallbacks.\n\n    Resolved on first use, not at import: Kaggle kernels install rapidfuzz from\n    offline wheels after the bundled modules are loaded. Both give the same answers.\n    """\n    global _DIST\n    if _DIST is None:\n        try:\n            from rapidfuzz.distance import DamerauLevenshtein, JaroWinkler\n\n            _DIST = (DamerauLevenshtein.distance, JaroWinkler.similarity)\n        except ImportError:\n            _DIST = (_py_dl, _py_jw)\n    return _DIST\n\n\n# Prior strengths used only to order links in the alignment (plan SS13.1);\n# the model sees counts per relation type and learns their real value.\nSTRENGTH = {\n    "exact": 1.00,\n    "fold_exact": 0.95,\n    "numeric_equal": 0.95,\n    "split_join": 0.90,\n    "typo": 0.85,\n    "prefix_abbrev": 0.80,\n    "initialism": 0.80,\n    "skeleton_abbrev": 0.70,\n    "short_abbrev": 0.45,  # 2-letter abbreviations ("st", "bd"): ambiguous, own counter (plan SS13.5)\n    "none": 0.0,\n}\n_ABBREV = ("prefix_abbrev", "skeleton_abbrev")\n_NUM_TOKEN = re.compile(r"^(\\d+)([a-z]*)$")\n_CACHE: dict[tuple[str, str], str] = {}\n_CACHE_MAX = 4_000_000\n_JOIN_MAX = 3  # split_join: one token vs up to 3 consecutive tokens\n_INIT_MAX_SPAN = 6  # initialism: letters matched over at most 6 consecutive tokens\n_INIT_SKIP_LEN = 3  # tokens this short may be skipped inside an initialism ("of", "&", "de")\n\n\ndef _num_base(tok: str) -> str | None:\n    """Digit base of a number-like token ("12bis" -> "12", "03" -> "3"); None if not number-like."""\n    m = _NUM_TOKEN.match(tok)\n    if not m:\n        return None\n    return m.group(1).lstrip("0") or "0"\n\n\n_DIGIT = re.compile(r"\\d")\n\n\ndef _has_digit(tok: str) -> bool:\n    """True if the token contains any digit."""\n    return _DIGIT.search(tok) is not None\n\n\ndef _is_subsequence(short: str, long: str) -> bool:\n    """True if `short`\'s letters appear in `long` in order (plan SS28.4)."""\n    it = iter(long)\n    return all(ch in it for ch in short)\n\n\n_FOLD_CACHE: dict[str, str] = {}\n\n\ndef _fold_token(tok: str) -> str:\n    """Look-alike digits back to letters, then the phonetic fold of normalize.py (cached)."""\n    f = _FOLD_CACHE.get(tok)\n    if f is None:\n        if len(_FOLD_CACHE) >= _CACHE_MAX:\n            _FOLD_CACHE.clear()\n        f = _FOLD_CACHE[tok] = normalize.fold(blocking.deleet(tok))\n    return f\n\n\ndef _relation(a: str, b: str) -> str:\n    """Uncached relation between two single tokens (see `token_relation`)."""\n    if a == b:\n        return "exact"\n    da, db = blocking.deleet(a), blocking.deleet(b)\n    na, nb = _has_digit(da), _has_digit(db)\n    if na or nb:\n        # Numbers are never typos or abbreviations of each other: 12 vs 13 is a conflict.\n        ba, bb = _num_base(da), _num_base(db)\n        if ba is not None and ba == bb:\n            return "numeric_equal"\n        return "exact" if da == db else "none"\n    if da == db:\n        return "fold_exact"\n    fa, fb = _fold_token(a), _fold_token(b)\n    if fa == fb:\n        return "fold_exact"\n    s, l = (da, db) if len(da) <= len(db) else (db, da)\n    if len(s) >= 3:\n        lim = 1 if len(l) <= 5 else 2\n        dl, jw = _distances()\n        if dl(da, db) <= lim or dl(fa, fb) <= lim or jw(da, db) >= 0.92:\n            return "typo"\n    if len(s) < 2 or len(s) >= len(l):\n        return "none"\n    if l.startswith(s):\n        return "short_abbrev" if len(s) == 2 else "prefix_abbrev"\n    if s[0] == l[0] and len(s) <= 0.7 * len(l) and _is_subsequence(s, l):\n        return "short_abbrev" if len(s) == 2 else "skeleton_abbrev"\n    return "none"\n\n\ndef token_relation(a: str, b: str) -> str:\n    """Relation type between two normalised tokens (symmetric, cached).\n\n    Tests, strongest first (plan SS13.1): exact; fold_exact (same after\n    look-alike-digit and phonetic fold); numeric_equal (same digit base,\n    e.g. 12 vs 12bis); typo (Damerau-Levenshtein <= 1 for length <= 5, <= 2\n    above, or Jaro-Winkler >= 0.92; both tokens >= 3 letters); prefix_abbrev\n    and skeleton_abbrev (same first letter, ordered subsequence, length ratio\n    <= 0.7); abbreviations of only 2 letters become the weak `short_abbrev`.\n    Multi-token relations (split_join, initialism) are found in `align`.\n\n    Inputs: a, b - tokens. Outputs: relation name (a key of STRENGTH).\n    """\n    key = (a, b) if a <= b else (b, a)\n    r = _CACHE.get(key)\n    if r is None:\n        if len(_CACHE) >= _CACHE_MAX:\n            _CACHE.clear()\n        r = _CACHE[key] = _relation(*key)\n    return r\n\n\ndef _initialism_span(acr: str, toks: list[str], free: list[bool]) -> list[int] | None:\n    """Token positions whose initials spell `acr`, over consecutive free tokens.\n\n    Short tokens (<= 3 chars, e.g. "of", "&") may be skipped inside the span,\n    so "sbi" matches "state bank of india" without any word list.\n    Inputs: acr - candidate initialism (2-5 letters); toks; free - usable flags.\n    Outputs: list of positions (first letters consumed), or None.\n    """\n    n = len(toks)\n    for start in range(n):\n        if not free[start] or not toks[start] or toks[start][0] != acr[0]:\n            continue\n        used, k, j = [], 0, start\n        while j < n and j - start < _INIT_MAX_SPAN and k < len(acr) and free[j]:\n            t = toks[j]\n            if t and t[0] == acr[k]:\n                used.append(j)\n                k += 1\n            elif len(t) > _INIT_SKIP_LEN or k == 0:\n                break\n            j += 1\n        if k == len(acr) and len(used) >= 2:\n            return list(range(start, used[-1] + 1))\n    return None\n\n\ndef _join_span(tok: str, toks: list[str], free: list[bool]) -> list[int] | None:\n    """Positions of 2-3 consecutive free tokens whose concatenation equals `tok` (exact or folded)."""\n    ft = None\n    n = len(tok)\n    for start in range(len(toks)):\n        cat = ""\n        for j in range(start, min(len(toks), start + _JOIN_MAX)):\n            if not free[j]:\n                break\n            cat += toks[j]\n            if j > start and abs(len(cat) - n) <= 2:\n                if cat == tok:\n                    return list(range(start, j + 1))\n                if ft is None:\n                    ft = _fold_token(tok)\n                if _fold_token(cat) == ft:\n                    return list(range(start, j + 1))\n            if len(cat) >= n + 2:\n                break\n    return None\n\n\ndef align(t1: list[str], t2: list[str]) -> dict:\n    """Align two token lists and label every token explained/unexplained (plan SS13.2).\n\n    Steps: (1) exact matches; (2) multi-token links, split_join and\n    initialism, in both directions among the remaining tokens; (3) greedy\n    maximum-strength 1-to-1 links among the rest (tokens are few, so greedy\n    by strength gives the same result as the Hungarian step in practice and\n    is much faster).\n\n    Inputs: t1, t2 - token lists of the same field of two records.\n    Outputs: dict with\n      links: list of (positions_1, positions_2, relation);\n      rel1/rel2: relation per token (None = unexplained).\n    """\n    n1, n2 = len(t1), len(t2)\n    rel1: list[str | None] = [None] * n1\n    rel2: list[str | None] = [None] * n2\n    links: list[tuple[list[int], list[int], str]] = []\n\n    # (1) exact matches first, left to right\n    pos2: dict[str, list[int]] = {}\n    for j, t in enumerate(t2):\n        pos2.setdefault(t, []).append(j)\n    for i, t in enumerate(t1):\n        js = pos2.get(t)\n        if js:\n            j = js.pop(0)\n            rel1[i] = rel2[j] = "exact"\n            links.append(([i], [j], "exact"))\n    if all(rel1) and all(rel2):\n        return {"links": links, "rel1": rel1, "rel2": rel2}\n\n    # (2) multi-token relations among unexplained tokens\n    for src, dst, rs, rd, flip in ((t1, t2, rel1, rel2, False), (t2, t1, rel2, rel1, True)):\n        for i, tok in enumerate(src):\n            if rs[i] is not None or _has_digit(tok):\n                continue\n            free = [r is None for r in rd]\n            span = _join_span(tok, dst, free) if len(tok) >= 4 else None\n            rel = "split_join"\n            if span is None and 2 <= len(tok) <= 5:\n                span = _initialism_span(tok, dst, free)\n                rel = "initialism"\n            if span is not None:\n                rs[i] = rel\n                for j in span:\n                    rd[j] = rel\n                links.append((span, [i], rel) if flip else ([i], span, rel))\n\n    # (3) greedy 1-to-1 links among the rest\n    free1 = [i for i in range(n1) if rel1[i] is None]\n    free2 = [j for j in range(n2) if rel2[j] is None]\n    if free1 and free2:\n        cand = []\n        for i in free1:\n            a = t1[i]\n            for j in free2:\n                r = token_relation(a, t2[j])\n                if r != "none":\n                    # tie-break: prefer links between close positions (keeps order)\n                    cand.append((-STRENGTH[r], abs(i / max(n1, 1) - j / max(n2, 1)), i, j, r))\n        cand.sort()\n        for _, _, i, j, r in cand:\n            if rel1[i] is None and rel2[j] is None:\n                rel1[i] = rel2[j] = r\n                links.append(([i], [j], r))\n    return {"links": links, "rel1": rel1, "rel2": rel2}\n\n\ndef _kendall_tau(pairs: list[tuple[int, int]]) -> float:\n    """Kendall tau between aligned positions (1.0 = same order); NaN if < 2 links."""\n    n = len(pairs)\n    if n < 2:\n        return float("nan")\n    conc = disc = 0\n    for x in range(n):\n        for y in range(x + 1, n):\n            s = (pairs[x][0] - pairs[y][0]) * (pairs[x][1] - pairs[y][1])\n            if s > 0:\n                conc += 1\n            elif s < 0:\n                disc += 1\n    tot = conc + disc\n    return (conc - disc) / tot if tot else float("nan")\n\n\nFIELD_FEATURES = [\n    "expl_frac_idf", "expl_frac_idf_min", "unexpl_max_idf_1", "unexpl_max_idf_2", "unexpl_sum_idf_1",\n    "unexpl_sum_idf_2", "n_exact", "n_fold", "n_typo", "n_abbrev", "n_short_abbrev", "n_initialism",\n    "n_splitjoin", "n_numeq", "n_dropped_generic", "n_unexpl", "n_unexpl_1", "n_unexpl_2", "order_tau",\n    "core_equal", "first_explained", "ntok_1", "ntok_2",\n]\n\n\ndef explain_features(\n    t1: list[str], t2: list[str], idf1: list[float], idf2: list[float], generic1: list[bool], generic2: list[bool]\n) -> tuple[list[float], dict]:\n    """Features for one field of one pair (plan SS13.3), plus the alignment.\n\n    Unexplained tokens flagged generic (suffix-/street-type-like, decided by\n    corpus statistics, not word lists) count as `dropped_generic`; the others\n    are unexplained content, the strong negative evidence.\n\n    Inputs: t1, t2 - tokens; idf1, idf2 - IDF per token; generic1/2 - flags.\n    Outputs: (values in FIELD_FEATURES order, alignment dict from `align`).\n    """\n    al = align(t1, t2)\n    rel1, rel2 = al["rel1"], al["rel2"]\n    tot1, tot2 = sum(idf1), sum(idf2)\n    ex1 = sum(w for w, r in zip(idf1, rel1) if r is not None)\n    ex2 = sum(w for w, r in zip(idf2, rel2) if r is not None)\n    nan = float("nan")\n    frac = (ex1 + ex2) / (tot1 + tot2) if tot1 + tot2 > 0 else nan\n    frac_min = min(ex1 / tot1 if tot1 > 0 else 1.0, ex2 / tot2 if tot2 > 0 else 1.0) if t1 and t2 else nan\n    u1 = [w for w, r, g in zip(idf1, rel1, generic1) if r is None and not g]\n    u2 = [w for w, r, g in zip(idf2, rel2, generic2) if r is None and not g]\n    n_gen = sum(1 for r, g in zip(rel1, generic1) if r is None and g) + sum(\n        1 for r, g in zip(rel2, generic2) if r is None and g\n    )\n    cnt = {"exact": 0, "fold_exact": 0, "typo": 0, "abbrev": 0, "short_abbrev": 0, "initialism": 0,\n           "split_join": 0, "numeric_equal": 0}\n    one_to_one = []\n    for p1, p2, r in al["links"]:\n        cnt["abbrev" if r in _ABBREV else r] += 1\n        if len(p1) == 1 and len(p2) == 1:\n            one_to_one.append((p1[0], p2[0]))\n    first = float(bool(t1) and bool(t2) and rel1[0] is not None and rel2[0] is not None)\n    vals = [\n        frac, frac_min,\n        max(u1) if u1 else 0.0, max(u2) if u2 else 0.0, sum(u1), sum(u2),\n        cnt["exact"], cnt["fold_exact"], cnt["typo"], cnt["abbrev"], cnt["short_abbrev"], cnt["initialism"],\n        cnt["split_join"], cnt["numeric_equal"], n_gen, len(u1) + len(u2), len(u1), len(u2),\n        _kendall_tau(one_to_one),\n        float(not u1 and not u2), first, len(t1), len(t2),\n    ]\n    return vals, al\n\n\n# ---------------------------------------------------------------------------\n# Number agreement (plan SS13.4)\n# ---------------------------------------------------------------------------\n# Relation codes (ordinal on purpose: missing < equal-ish < conflict is not\n# implied; LightGBM splits on the codes freely).\nREL_BOTH_MISSING, REL_ONE_MISSING, REL_EQUAL, REL_BASE_EQUAL, REL_PREFIX_EQUAL, REL_CONFLICT = 0, 1, 2, 3, 4, 5\n\nNUMBER_FEATURES = [\n    "house_no_rel", "postcode_rel", "unit_rel", "name_number_rel", "any_number_conflict", "house_in_other",\n    "n_shared_numbers", "jaccard_numbers", "n_numbers_1", "n_numbers_2",\n]\n\n\ndef _bases(tokens: list[str]) -> set[str]:\n    """Digit bases of the number-like tokens in a list."""\n    out = set()\n    for t in tokens:\n        b = _num_base(t)\n        if b is not None:\n            out.add(b)\n    return out\n\n\ndef _set_rel(a: set[str], b: set[str]) -> int:\n    """equal (share any) / conflict (both present, disjoint) / missing codes for two number sets."""\n    if not a and not b:\n        return REL_BOTH_MISSING\n    if not a or not b:\n        return REL_ONE_MISSING\n    return REL_EQUAL if a & b else REL_CONFLICT\n\n\ndef house_relation(h1: str, h2: str) -> int:\n    """House-number relation: equal / base-equal (12 vs 12bis, 12 vs 12b) / conflict / missing."""\n    if not h1 and not h2:\n        return REL_BOTH_MISSING\n    if not h1 or not h2:\n        return REL_ONE_MISSING\n    if h1 == h2:\n        return REL_EQUAL\n    b1, b2 = _num_base(h1), _num_base(h2)\n    if b1 is not None and b1 == b2:\n        return REL_BASE_EQUAL\n    return REL_CONFLICT\n\n\ndef postcode_relation(p1: list[str], p2: list[str]) -> int:\n    """Postcode relation: equal / first-3-characters equal / conflict / missing."""\n    if not p1 and not p2:\n        return REL_BOTH_MISSING\n    if not p1 or not p2:\n        return REL_ONE_MISSING\n    if set(p1) & set(p2):\n        return REL_EQUAL\n    if {x[:3] for x in p1 if len(x) >= 4} & {x[:3] for x in p2 if len(x) >= 4}:\n        return REL_PREFIX_EQUAL\n    return REL_CONFLICT\n\n\ndef number_features(r1: dict, r2: dict) -> list[float]:\n    """Number agreement features of a record pair (plan SS13.4).\n\n    Inputs: r1, r2 - dicts with house_number (str), postcodes, addr_numbers,\n            name_numbers (space-separated strings, as written by normalize.py).\n    Outputs: values in NUMBER_FEATURES order.\n    """\n    h1, h2 = r1["house_number"], r2["house_number"]\n    pc1, pc2 = r1["postcodes"].split(), r2["postcodes"].split()\n    a1, a2 = r1["addr_numbers"].split(), r2["addr_numbers"].split()\n    nn1, nn2 = _bases(r1["name_numbers"].split()), _bases(r2["name_numbers"].split())\n    # unit/other numbers = address numbers that are neither the house number nor a postcode\n    u1 = _bases([t for t in a1 if t != h1 and t not in pc1])\n    u2 = _bases([t for t in a2 if t != h2 and t not in pc2])\n    hr = house_relation(h1, h2)\n    pr = postcode_relation(pc1, pc2)\n    ur = _set_rel(u1, u2)\n    nr = _set_rel(nn1, nn2)\n    all1 = _bases(a1) | nn1\n    all2 = _bases(a2) | nn2\n    shared = all1 & all2\n    union = all1 | all2\n    hb1, hb2 = _num_base(h1) if h1 else None, _num_base(h2) if h2 else None\n    house_in_other = float((hb1 is not None and hb1 in all2) or (hb2 is not None and hb2 in all1))\n    conflict = float(\n        (hr == REL_CONFLICT and not house_in_other) or pr == REL_CONFLICT or nr == REL_CONFLICT\n    )\n    return [\n        hr, pr, ur, nr, conflict, house_in_other,\n        len(shared), len(shared) / len(union) if union else float("nan"), len(all1), len(all2),\n    ]\n\n\ndef main() -> None:\n    """Print the relation of a few example token pairs (smoke test)."""\n    for a, b in [("corp", "corporation"), ("pvt", "private"), ("bd", "boulevard"), ("st", "south"),\n                 ("12", "12bis"), ("glypheus", "glypheos")]:\n        print(f"{a!r} ~ {b!r}: {token_relation(a, b)}")\n    print(align("state bank of india".split(), ["sbi"])["links"])\n    print(align(["walmart"], "wal mart".split())["links"])\n\n\nif __name__ == "__main__":\n    main()\n'
